'use strict';
// Bài 11.2 — this trong hẹn giờ
function makeClock() {
  return {
    seconds: 0,
    onTick: null,
    startAfter(ms) {
      setTimeout(function () {
        this.seconds++;
        if (this.onTick) this.onTick(this.seconds);
      }, ms);
    },
  };
}

solutionCodeJson.code:
'use strict';
// Bài 11.2 — arrow không có this riêng ⇒ dùng this của startAfter (chính đồng hồ)
function makeClock() {
  return {
    seconds: 0,
    onTick: null,
    startAfter(ms) {
      setTimeout(() => {
        this.seconds++;                                   // this = clock vì ta gọi clock.startAfter()
        if (this.onTick) this.onTick(this.seconds);
      }, ms);
    },
  };
}

